import polars as pl

s = pl.Series("a", [3, 1, 2])

try:
    s.item()
except ValueError:
    print("ValueError")

print(s.item(0))    # 3
print(s.item(-1))   # 2
print(s.filter(s > 2).item())  # 3 -- exactly one match

try:
    s.filter(s > 1).item()  # two matches
except ValueError:
    print("ValueError")
